-- Q14 engine.records last five plus row e6aacb34 (Dholakia). Ruled YES at CE-43 (c-43.2). witness: ENGINE_SCHEMA.md:310-333 (engine.records all 21; 0155-0166 do not touch it) + ENGINE_SCHEMA.md:349-353 (engine.users) + info_schema paste (public.users id,phone,auth_user_id; engine.agents id,user_id).
with pu as (select id, auth_user_id from public.users where phone ~ '9888294440$'), ag as (select a.id from engine.agents a join engine.users eu on eu.id = a.user_id join pu on pu.auth_user_id = eu.auth_user_id), last5 as (select id from engine.records where agent_id in (select id from ag) order by created_at desc limit 5) select id, agent_id, client, phone, date, stage, amount, direction, amount_received, amount_pending, payment_status, followup_on, followup_note, repeat_every, doc_ref, note, reason_for_action, hidden, hidden_at, created_at, updated_at from engine.records where agent_id in (select id from ag) and (id in (select id from last5) or id = 'e6aacb34-2e05-4729-9be9-7921e09e6f62') order by created_at desc;

